"""Build an offline, embedded representative review without a server."""
import base64,json,html
from pathlib import Path
root=Path('.artifacts/m1-7-yr');manifest=json.loads((root/'review-exports-v2/manifest.json').read_text())
esc=html.escape
uri=lambda p:'data:image/png;base64,'+base64.b64encode(Path(p).read_bytes()).decode()
names={'BORIS':'Boris','CCOMAND':'Chrono Commando','PTROOP':'Psi Commando','SCHP':'Siege Chopper','BPLN':'MiG airstrike aircraft'}
sections=[]
for f in sorted(manifest['families'],key=lambda f:['BORIS','CCOMAND','PTROOP','SCHP','BPLN'].index(f['id'])):
 id=f['id'];cards=[]
 for s in f['samples']:
  w,h=s['displaySize'];cards.append(f'''<div class="sample"><strong>{esc(s['label'])}</strong><div class="pair"><figure><div class="stage"><img class="sprite original" style="--w:{w}px;--h:{h}px" src="{uri(s['original'])}"></div><figcaption>Original</figcaption></figure><figure><div class="stage"><img class="sprite" style="--w:{w}px;--h:{h}px" src="{uri(s['hd'])}"></div><figcaption>HD candidate</figcaption></figure></div></div>''')
 note='Includes required aircraft dependency BPLN.' if id=='BORIS' else 'Requires stolen Allied technology.' if id=='CCOMAND' else 'Requires stolen Yuri technology.' if id=='PTROOP' else 'Flight and deployed representatives. Full rotors, transition and independent turret production pending.' if id=='SCHP' else 'Required child of Boris; not counted as another buildable unit.'
 sections.append(f'''<section data-group="{'infantry' if id in ['BORIS','CCOMAND','PTROOP'] else 'air'}" id="{id}"><h2>{names[id]} <small>{id}</small></h2><p>{note}</p><div class="samples">{''.join(cards)}</div><details><summary>Enlarged authored sheet and exact native reference</summary><div class="boards"><img alt="{id} HD sheet" src="{uri(f['raw'])}"><img alt="{id} source sheet" src="{uri(f['sourceBoard'])}"></div></details></section>''')
text='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>YR Soviet Units — Representative Review 2</title><style>
:root{color-scheme:dark;--scale:1}*{box-sizing:border-box}body{margin:0;background:#17211c;color:#e8ece8;font:18px/1.5 system-ui,sans-serif}header,main{max-width:1380px;margin:auto;padding:24px}h1{font-size:32px;margin:0 0 12px}h2{font-size:28px}small{font-size:18px;color:#bdc8bf}p{max-width:1000px}.notice{padding:16px;background:#28372e;border-left:4px solid #d9aa5d}nav{position:sticky;top:0;background:#202e26;padding:14px 24px;z-index:2;display:flex;gap:18px;align-items:center;flex-wrap:wrap}button,select{font:inherit;color:inherit;background:#34483a;border:1px solid #718c77;border-radius:5px;padding:7px 12px}button[aria-pressed=true]{background:#657d43}section{margin:0 0 32px;border:1px solid #405648;border-radius:8px;padding:20px}.samples{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,calc(330px * var(--scale))),1fr));gap:15px}.sample{border:1px solid #3c5142;padding:10px;border-radius:4px;overflow:auto}.pair{width:max-content;margin:auto;display:flex;gap:12px;align-items:end;justify-content:center}figure{margin:8px 0;text-align:center}.stage{display:grid;place-items:center;min-height:120px;background:#48584e;padding:8px}.sprite{width:calc(var(--w)*var(--scale));height:calc(var(--h)*var(--scale));max-width:none}.original{image-rendering:pixelated}figcaption{font-size:15px;color:#bdc8bf}details{margin-top:18px}summary{cursor:pointer;font-size:19px}.boards{display:grid;grid-template-columns:1fr 1fr;gap:12px;padding-top:15px}.boards img{width:100%;height:auto;align-self:start}footer{padding:24px;color:#b7c1b8}[hidden]{display:none!important}@media(max-width:700px){.boards{grid-template-columns:1fr}.samples{grid-template-columns:1fr}header,main{padding:14px}}
</style><header><h1>YR Soviet Units · Representative Review 2</h1><p>4 new unit families + Boris's required MiG aircraft. Accepted RA2 artwork is preserved.</p><div class="notice">Review material, silhouette, proportions and native-size readability. These are representative samples, not complete animation packs or activated game replacements. Approve both groups together, or name exceptions.</div></header><nav><button aria-pressed="true" data-filter="all">All</button><button aria-pressed="false" data-filter="infantry">Infantry</button><button aria-pressed="false" data-filter="air">Air / deployed</button><label>Display <select id="scale"><option value="1">1× native reference</option><option value="2">2× inspection</option><option value="4">4× inspection</option></select></label></nav><main><p>Infantry previews retain original indexed shadows. Aircraft shadows will use native runtime shadows during integration; their absence in isolated sheets is not the intended game result. Static registration does not certify movement, firing scale or team-color behavior.</p>'''+''.join(sections)+'''</main><footer>Scope: 28 Soviet YR skirmish identities — 23 accepted HD reuses, Original SQD, 4 new families pending review. New complete runtime families: 0. Native deployment/reference evidence and explicit exclusions are recorded in the coverage ledger. All images are embedded; no network or server is needed.</footer><script>
for(const button of document.querySelectorAll('[data-filter]'))button.onclick=()=>{for(const b of document.querySelectorAll('[data-filter]'))b.setAttribute('aria-pressed',b===button);for(const s of document.querySelectorAll('section'))s.hidden=button.dataset.filter!=='all'&&s.dataset.group!==button.dataset.filter};document.querySelector('#scale').onchange=e=>document.documentElement.style.setProperty('--scale',e.target.value);
</script></html>'''
p=root/'YR-Soviet-Units-Review-v2.html';p.write_text(text);print(p,len(text))
